import {scanCan} from './scan.js';
import {ScenarioRunner,validateScenario} from './scenarios.js';
import {parseDdt} from './vendor/ddt.js';
import {demoDefinition,demoScenario,demoRequest} from './service-demo.js';
export function createWorkflows(ctx){
 const {$,esc,state,toast,render,updateStatus,job,download}=ctx;
 let scanning=false,scanController,scanReport=null,scanProgress='',scenario=null,running=false,serviceController,serviceEvents=[],serviceStatus='',serviceReport=null;
 let reports=[];try{reports=JSON.parse(localStorage.getItem('espace.serviceReports'))||[];if(!Array.isArray(reports))reports=[];}catch{}
 const demoEcu=()=>parseDdt(JSON.stringify(demoDefinition),'simulace.json');
 const chosenEcu=()=>state.demo?demoEcu():state.ecu;
 function scanView(){const rows=scanReport?.results||[];return `<div class="toolbar"><button id="startScan" class="primary" ${!state.connected||scanning||running?'disabled':''}>⟳ Automatický sken CAN</button><button id="stopScan" ${!scanning?'disabled':''}>Zastavit sken</button><button id="importScan">＋ Načíst databázi</button><button id="scanExport" ${!scanReport?'disabled':''}>↓ Výsledek skenu</button></div><div class="notice">Sken používá pouze CAN adresy z importovaných definic. Zjišťuje identifikaci UDS / KWP přes CAN a porovnává všechny čtyři identifikační údaje. „Odpovídá“ ještě nepotvrzuje správnou variantu ECU. K-line a DoIP nejsou skenovány.</div><div class="toolbar"><input id="scanFilter" placeholder="Filtr definic pro sken, např. název ECU…" aria-label="Filtr skenu" ${scanning?'disabled':''}><label class="small"><input type="checkbox" id="scanSessions" ${scanning?'disabled':''}> Při neúspěchu povolit identifikační relace 1003 / 10C0</label></div><div class="small" style="margin-bottom:15px">${esc(scanProgress||'Načteno '+ctx.getIndex().length+' definic. Před skenem zapněte zapalování a vyberte databázi správného vozu.')}</div><div class="panel table-scroll"><table><thead><tr><th>TX / RX</th><th>VÝSLEDEK</th><th>IDENTIFIKACE</th><th>DEFINICE</th><th></th></tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td>${esc(r.address)}</td><td class="${r.matches.length===1?'green':r.answered?'amber':'muted'}">${r.matches.length===1?'Shoda identifikace':r.matches.length>1?'Více shod – vyberte variantu':r.answered?'Odpovídá · bez shody':r.interrupted?'Přerušeno':'Bez odpovědi'}</td><td>${r.identity?esc([r.identity.diagversion,r.identity.supplier,r.identity.soft,r.identity.version].join(' / ')):'—'}</td><td>${esc((r.matches.length?r.matches:r.candidates).join(', '))}</td><td><button data-scan-open="${i}" ${r.matches.length!==1||scanning?'disabled':''}>Vybrat</button></td></tr>`).join(''):'<tr><td colspan="5"><div class="empty"><h3>Automatické hledání jednotek</h3><p>Načtěte definice v Expert · DDT a spusťte sken.<br>V demo režimu se použije pouze syntetická ECU.</p></div></td></tr>'}</tbody></table></div>${scanReport?.skipped?.length?`<p class="small">Přeskočené neplatné / nepodporované definice: ${scanReport.skipped.length}.</p>`:''}`;}
 function serviceView(){return `<div class="toolbar"><button id="loadScenario" class="primary" ${running?'disabled':''}>＋ Načíst servisní scénář JSON</button><input type="file" id="scenarioFile" accept=".json" hidden><button id="loadDemoScenario" ${running?'disabled':''}>Ukázkový scénář</button><button id="serviceExport" ${!serviceReport?'disabled':''}>↓ Protokol</button><button id="serviceHistory">↓ Historie (${reports.length})</button></div><div class="notice">Servisní runner provádí pouze importovaný postup pro přesnou ECU: kontroluje identifikační otisk, vstupní podmínky a výsledek. Samotný DDT soubor neobsahuje kompletní servisní scénář PyRenu. Automatický převod jeho Python/XML postupů ani databáze konkrétních DPF/vstřikovačů zatím nejsou zahrnuty.</div><div class="grid"><section class="panel cards-text"><span class="pill">ČTECÍ POSTUP</span><h3>Předservisní kontrola</h3><p>VIN, napájení, otáčky, teplota a emisní readiness bez změn konfigurace.</p><button id="healthScenario" ${!state.connected||running?'disabled':''}>Spustit kontrolu →</button></section><section class="panel cards-text"><span class="tag">DEFINOVANÝ POSTUP</span><h3>Rutina a sledování ECU</h3><p>Scénář JSON: kontroly, pevné UDS 31 příkazy, monitorování, ověření a definované zastavení.</p><button id="scenarioDocs">Formát a příklad →</button></section><section class="panel cards-text"><span class="tag">VYŽADUJE DATA ECU</span><h3>DPF / vstřikovače / ABS</h3><p>Neexistuje společný příkaz pro všechny Espace. Potřebujete přesnou dokumentaci a implementaci konkrétní procedury. Kódování vstřikovačů tímto runnerem není podporováno.</p></section></div><div class="panel help" style="margin-top:20px"><h2>${esc(scenario?.title||'Není načten servisní scénář')}</h2>${scenario?`<p>ECU: ${esc(scenario.target?.name)} · ${esc(scenario.target?.tx)} / ${esc(scenario.target?.rx)}<br>Zdroj: ${esc(scenario.reference)}${scenario.demoOnly?'<br><b class="amber">POUZE SIMULACE · nelze spustit s autem</b>':''}</p><ol>${(scenario.instructions||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="toolbar"><button id="prepareScenario" class="primary" ${!state.connected||running?'disabled':''}>Zkontrolovat a připravit spuštění</button><button id="cancelScenario" ${!running?'disabled':''}>Zastavit postup</button></div>`:'<p>Importujte JSON scénář a odpovídající DDT definici, nebo si vyzkoušejte simulaci.</p>'}<p id="serviceStatus" class="small">${esc(serviceStatus)}</p><pre id="serviceLog" class="code">${esc(eventText())}</pre></div>`;}
 function eventText(){return serviceEvents.slice(-150).map(e=>e.time.slice(11,19)+' '+e.type+' '+(e.title||e.message||e.label||e.request||'')+(e.value!=null?' = '+e.value:'')+(e.passed!=null?' · '+(e.passed?'OK':'NESPLNĚNO'):'')+(e.response?' → '+e.response:'')).join('\n')||'Zatím žádný průběh.';}
 function updateService(){if($('#serviceLog')){$('#serviceLog').textContent=eventText();$('#serviceLog').scrollTop=$('#serviceLog').scrollHeight;}if($('#serviceStatus'))$('#serviceStatus').textContent=serviceStatus;}
 async function startScan(){if(!state.connected)throw Error('Připojte adaptér nebo spusťte demo.');if(running)throw Error('Probíhá servisní postup.');const filter=$('#scanFilter').value.toLowerCase(),allowSessions=$('#scanSessions').checked;scanning=true;scanController=new AbortController();scanReport={results:[],skipped:[]};scanProgress='Připravuji definice…';const previous=state.ecu;state.paused=true;render();updateStatus();try{const ecus=[];if(state.demo)ecus.push(demoEcu());else{const candidates=ctx.getIndex().filter(e=>e.name.toLowerCase().includes(filter));if(!candidates.length)throw Error('Nejsou načtené žádné odpovídající DDT definice.');if(candidates.length>1500)throw Error('Výběr obsahuje více než 1500 definic. Omezte jej filtrem pro váš vůz.');for(const [i,d] of candidates.entries()){if(scanController.signal.aborted)break;try{ecus.push(await d.get());}catch(e){scanReport.skipped.push(d.name+': '+e.message);}if(i%25===0)await new Promise(r=>setTimeout(r,0));}}
 const simulated=demoRequest();const parseSkipped=[...scanReport.skipped];const report=await scanCan(ecus,{signal:scanController.signal,allowSessions,request:state.demo?async(e,q)=>simulated(q):ctx.scanRequest,onProgress:p=>{scanReport.results.push(p.row);scanProgress=`${p.done} / ${p.total} CAN adres · nalezeno ${scanReport.results.filter(r=>r.answered).length} odpovídajících`;if(state.view==='ecus')render();}});scanReport={...report,skipped:[...parseSkipped,...report.skipped],time:new Date().toISOString(),simulated:state.demo,vin:state.vin,profile:ctx.getSettings().profile};scanProgress+=(report.cancelled?' · Zastaveno uživatelem':' · Dokončeno');}finally{state.ecu=previous;scanning=false;if(state.view==='ecus')render();}}
 async function prepareScenario(){const ecu=chosenEcu();if(!ecu)throw Error('Nejprve vyberte přesnou DDT ECU.');const valid=validateScenario(scenario,ecu);if(valid.demoOnly&&!state.demo)throw Error('Tento scénář funguje jen v demo režimu.');if(!state.demo&&!state.vin)throw Error('Nejprve načtěte platné VIN vozidla.');const vin=state.vin;ctx.modal(`<h2>Spustit servisní postup?</h2><p>${esc(valid.title)}<br>${esc(ecu.name)} · VIN ${esc(vin)}</p><p>Postup může ovládat zařízení vozidla. Potvrďte, že jste ověřili dokumentaci, všechny uvedené pokyny a stabilní napájení. Přerušení spojení nezaručuje zastavení rutiny ECU.</p><label class="field"><span><input type="checkbox" id="scenarioAck"> Ověřil jsem dokumentaci a podmínky postupu</span></label><div class="field"><label for="scenarioConfirm">Napište SPUSTIT</label><input id="scenarioConfirm" autocomplete="off"></div><button id="runScenario" class="primary full" disabled>Spustit a zaznamenávat</button>`);const unlock=()=>$('#runScenario').disabled=!$('#scenarioAck').checked||$('#scenarioConfirm').value!=='SPUSTIT';$('#scenarioAck').onchange=unlock;$('#scenarioConfirm').oninput=unlock;$('#runScenario').onclick=()=>job(async()=>{if(!$('#scenarioAck').checked||$('#scenarioConfirm').value!=='SPUSTIT')return;if(state.vin!==vin||(!state.demo&&state.ecu!==ecu))throw Error('Vozidlo nebo ECU se změnily.');$('#modal').close();await runScenario(valid,ecu);});}
 function saveReports(){localStorage.setItem('espace.serviceReports',JSON.stringify(reports.slice(-20)));}
 async function runScenario(s,ecu){running=true;serviceController=new AbortController();serviceEvents=[];serviceStatus='Probíhá…';state.paused=true;serviceReport={time:new Date().toISOString(),title:s.title,vin:state.vin,simulated:state.demo,ecu:ecu.name,status:'Probíhá / po přerušení stránky může být stav ECU nejistý',events:[]};reports.push(serviceReport);saveReports();render();updateStatus();try{const sim=demoRequest();const runner=new ScenarioRunner({ecu,signal:serviceController.signal,request:state.demo?sim:q=>ctx.scanRequest(ecu,q,3500),persist:events=>{serviceReport.events=events.slice(-1000);saveReports();},onEvent:e=>{serviceEvents.push(e);updateService();}});const result=await runner.run(s,{demo:state.demo});serviceStatus=result.status+(result.error?' · '+result.error:'');serviceReport.status=serviceStatus;saveReports();toast(serviceStatus);}finally{running=false;render();}}
 async function health(){state.paused=true;updateStatus();const data=await ctx.healthCheck();serviceReport={time:new Date().toISOString(),title:'Předservisní kontrola',vin:state.vin,simulated:state.demo,...data};reports.push(serviceReport);saveReports();serviceEvents=[{time:new Date().toISOString(),type:'report',message:JSON.stringify(data,null,2)}];serviceStatus='Čtecí kontrola dokončena. Nenačtené parametry nejsou vyhodnoceny.';render();}
 function bind(){ $('#startScan')?.addEventListener('click',()=>job(startScan));$('#stopScan')?.addEventListener('click',()=>scanController?.abort());$('#importScan')?.addEventListener('click',()=>location.hash='expert');$('#scanExport')?.addEventListener('click',()=>download('espace-scan.json',JSON.stringify(scanReport,null,2)));document.querySelectorAll('[data-scan-open]').forEach(b=>b.onclick=()=>job(async()=>{const row=scanReport.results[Number(b.dataset.scanOpen)],name=row.matches[0];if(state.demo){state.ecu=demoEcu();}else{const d=ctx.getIndex().find(d=>d.name===name);if(!d)throw Error('Definice již není načtená.');state.ecu=await d.get();}state.ddtResults=[];state.paused=true;location.hash='expert';}));$('#loadScenario')?.addEventListener('click',()=>$('#scenarioFile').click());$('#scenarioFile')?.addEventListener('change',e=>job(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>200000)throw Error('Scénář je příliš velký (max 200 kB).');const ecu=chosenEcu();if(!ecu)throw Error('Vyberte nejprve DDT ECU nebo spusťte demo.');scenario=validateScenario(JSON.parse(await f.text()),ecu);serviceStatus='Scénář načten. Před spuštěním se provede živá kontrola identifikace a podmínek.';render();}));$('#loadDemoScenario')?.addEventListener('click',()=>{if(running)return;scenario=demoScenario;serviceStatus='Pro spuštění aktivujte demo režim.';render();});$('#prepareScenario')?.addEventListener('click',()=>job(prepareScenario));$('#cancelScenario')?.addEventListener('click',()=>{serviceController?.abort();serviceStatus='Žádám o ukončení; čeká se na dokončení příkazu a potvrzení zastavení ECU.';updateService();});$('#healthScenario')?.addEventListener('click',()=>job(health));$('#serviceExport')?.addEventListener('click',()=>download('espace-service.json',JSON.stringify(serviceReport,null,2)));$('#serviceHistory')?.addEventListener('click',()=>download('espace-service-history.json',JSON.stringify(reports,null,2)));$('#scenarioDocs')?.addEventListener('click',()=>{ctx.modal('<h2>Servisní scénáře</h2><p>Pro skutečný vůz potřebujete přesný postup, DDT definici a dokumentaci ECU. Přiložené JSON soubory jsou pouze pro simulaci a hardware je odmítne.</p><p><a href="SERVICE-SCENARIOS.md" download>↓ Podrobný návod a formát</a></p><p><a href="examples/demo-service.json" download>↓ Ukázkový scénář JSON</a></p><p><a href="examples/demo-ecu.json" download>↓ Syntetická ECU JSON</a></p>');});}
 return {scanView,serviceView,bind,isRunning:()=>scanning||running};
}
